"""SolarVision: one entry point for forecasting, thermal classification and maintenance.

Place this file at the repository root. Existing data/model folders are required.
Python 3.10+; install:
  pip install streamlit pandas numpy pillow tensorflow joblib scikit-learn
Run from any directory:
  streamlit run /path/to/SolarVision/solarvision_app.py

CSV input: timestamp, actual_power_W, predicted_power_W (optional is_daytime).
Rows must be hourly. Saved test predictions are historical demonstration data.
Forecast JSON: a complete feature-name/value object from the preprocessing pipeline;
this app does not manufacture training features from raw sensor readings.
"""
from pathlib import Path
import base64
from io import BytesIO
import json
import numpy as np
import pandas as pd

# Embedded project logo for the browser tab.
SOLARVISION_LOGO = ''

ROOT = Path(__file__).resolve().parent
TS = ROOT / 'SolarVision_TimeSeries_Feature-main' / 'SolarVision_TimeSeries_Feature-main'
CV = ROOT / 'Solar-Panel-Anomaly-Detection-main' / 'Solar-Panel-Anomaly-Detection-main'


def analyze(frame, drop=0.2):
    df = frame.copy()
    df.index = pd.to_datetime(df.index, errors='raise', utc=True)
    df = df.sort_index()
    if df.empty or df.index.hasnans or df.index.has_duplicates:
        raise ValueError('Supply nonempty data with unique valid timestamps.')
    if len(df) > 1 and not (df.index.to_series().diff().dropna() == pd.Timedelta(hours=1)).all():
        raise ValueError('Data must contain consecutive hourly readings; fill gaps explicitly first.')
    for col in ['actual_power_W', 'predicted_power_W']:
        df[col] = pd.to_numeric(df[col], errors='raise')
        if not np.isfinite(df[col]).all() or (df[col] < 0).any():
            raise ValueError(f'{col} must contain finite nonnegative watts.')
    day = df['predicted_power_W'] >= 5
    if 'is_daytime' in df:
        values = df['is_daytime'].astype(str).str.lower()
        if not values.isin(['true', 'false', '0', '1', '0.0', '1.0']).all():
            raise ValueError('is_daytime must be boolean or 0/1.')
        day &= values.isin(['true', '1', '1.0'])
    df['anomaly'] = day & (df.actual_power_W <= df.predicted_power_W * (1-drop))
    df['alert'] = df.anomaly.rolling(6, min_periods=1).sum() >= 3
    alert_days = df.index.normalize()[df.alert]
    affected = day & df.index.normalize().isin(alert_days)
    loss = float((df.predicted_power_W-df.actual_power_W).clip(lower=0)[affected].sum()/1000)
    return df, loss


def maintenance(has_alert, label, confidence, matched, net, threshold=0.7):
    if not matched or label is None:
        return 'Investigate the production shortfall. Confirm a matching thermal inspection to assess the cause.' if has_alert else 'Continue monitoring. Add a matching thermal inspection for a combined recommendation.'
    if confidence < threshold:
        return 'Request a manual image review; the model score is too low for a recommendation.'
    if label == 'Soiling':
        if has_alert and net > 0:
            return 'Consider cleaning. The image suggests soiling, output is below expectations and the estimated benefit is positive.'
        return 'Inspect possible soiling; cleaning is not supported by both alert and economics.'
    if label == 'No-Anomaly':
        return 'Investigate weather, sensors or other causes of shortfall.' if has_alert else 'Monitor: no thermal anomaly predicted.'
    return f'Inspect {label}; use the thermal maintenance guidance below before considering cleaning.'


def thermal_gradcam(model, batch, class_index):
    """Explain the predicted class using the last convolution's activations.

    Use pre-softmax logits for a final Dense classifier to avoid saturated
    probabilities. Do not change the cached model's activation or weights.
    """
    import tensorflow as tf
    layers = [layer for layer in model.layers if isinstance(layer, tf.keras.layers.Conv2D)]
    if not layers:
        raise ValueError('No convolutional layer is available for Grad-CAM.')
    conv = next((layer for layer in layers if layer.name == 'last_conv_layer'), layers[-1])
    final = model.layers[-1]
    use_logits = isinstance(final, tf.keras.layers.Dense)
    target = final.input if use_logits else model.output
    probe = tf.keras.Model(model.inputs, [conv.output, target])
    with tf.GradientTape() as tape:
        activations, features = probe(batch, training=False)
        if use_logits:
            outputs = tf.linalg.matmul(features, final.kernel)
            if final.use_bias:
                outputs = outputs + final.bias
        else:
            outputs = features
        score = outputs[:, class_index]
    gradients = tape.gradient(score, activations)
    if gradients is None:
        raise ValueError('The classifier is not connected to the selected convolution.')
    weights = tf.reduce_mean(gradients, axis=(1, 2), keepdims=True)
    heatmap = tf.nn.relu(tf.reduce_sum(weights * activations, axis=-1))[0]
    peak = float(tf.reduce_max(heatmap))
    if not np.isfinite(heatmap.numpy()).all():
        raise ValueError('The explanation contains nonfinite values.')
    return (heatmap.numpy() / peak if peak > 0 else np.zeros_like(heatmap.numpy())), conv.name


def gradcam_images(image, heatmap):
    """Render the explanation at the original image size with a blue-red scale."""
    from PIL import Image
    values = np.asarray(Image.fromarray(np.asarray(heatmap, dtype=np.float32)).resize(image.size, Image.Resampling.BILINEAR))
    values = np.clip(values, 0, 1)
    # A compact jet-like scale; red indicates stronger positive contribution.
    colors = np.stack([np.clip(1.5-np.abs(4*values-3),0,1),
                       np.clip(1.5-np.abs(4*values-2),0,1),
                       np.clip(1.5-np.abs(4*values-1),0,1)], axis=-1)
    colored = Image.fromarray(np.uint8(colors*255))
    overlay = Image.blend(image.convert('RGB'), colored, 0.4)
    return colored, overlay


def main():
    import streamlit as st
    from PIL import Image
    tab_logo = Image.open(BytesIO(base64.b64decode(SOLARVISION_LOGO)))
    st.set_page_config(page_title='SolarVision', page_icon=tab_logo, layout='wide')
    st.markdown("""<style>
    .stApp {background:#0b1220;color:#e7edf8;}
    .block-container {max-width:1280px;padding-top:2rem;padding-bottom:4rem;}
    [data-testid="stSidebar"] {background:#111c30;border-right:1px solid #25324a;}
    [data-testid="stSidebar"] * {color:#e7edf8;}
    h1,h2,h3,p,label,[data-testid="stMarkdownContainer"] {color:#e7edf8;}
    .sv-hero {display:flex;align-items:center;gap:28px;background:linear-gradient(120deg,#132b4b,#142139 65%,#29301d);border:1px solid #30415c;border-radius:24px;padding:28px 32px;margin-bottom:24px;}
    .sv-logo {width:126px;height:126px;object-fit:contain;background:#fff;border-radius:22px;flex-shrink:0;}
    .sv-eyebrow {font-size:11px;letter-spacing:3px;font-weight:700;color:#f9c74f;margin-bottom:6px;}
    .sv-title {font-size:clamp(30px,4vw,46px);font-weight:800;letter-spacing:-1.5px;line-height:1.1;margin:0 0 10px;}
    .sv-subtitle {font-size:15px;color:#b7c9e4;line-height:1.6;margin:0;}
    .sv-chips {display:flex;gap:8px;flex-wrap:wrap;margin-top:16px;}
    .sv-chip {padding:5px 10px;border:1px solid #41526b;border-radius:30px;font-size:11px;color:#d5e6fd;background:#14243a;}
    .sv-section {margin:30px 0 14px;display:flex;align-items:center;gap:12px;}
    .sv-number {display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:#15375a;color:#5ac8fa;font-weight:800;font-size:13px;}
    .sv-section-title {font-size:23px;font-weight:700;letter-spacing:-.4px;}
    .sv-section-sub {font-size:13px;color:#9eb0ca;margin-top:3px;}
    [data-testid="stMetric"] {background:#142139;border:1px solid #2b3b55;border-radius:16px;padding:18px 20px;}
    [data-testid="stMetricLabel"] p {color:#a9bbd5;font-size:12px;}
    [data-testid="stMetricValue"] {color:#f7c85b;font-size:30px;font-weight:700;}
    [data-testid="stExpander"] {border:1px solid #2b3b55;border-radius:12px;background:#101b2e;}
    [data-testid="stFileUploader"] {border:1px dashed #425b7d;border-radius:14px;padding:8px;background:#132139;}
    [data-testid="stFileUploaderDropzone"] {background:#132139;color:#e7edf8;}
    .stButton button,.stDownloadButton button {border-radius:10px;border:1px solid #3d739d;background:#163c5e;color:#edf6ff;font-weight:600;}
    .stButton button:hover,.stDownloadButton button:hover {border-color:#f9c74f;color:#f9c74f;}
    [data-testid="stCaptionContainer"] p {color:#9eb0ca;line-height:1.6;}
    .sv-footer {border-top:1px solid #29374c;margin-top:36px;padding-top:18px;font-size:12px;color:#9eb0ca;}
    @media(max-width:640px) {.sv-hero {padding:20px;gap:16px;align-items:flex-start;} .sv-logo{width:72px;height:72px;border-radius:14px;} .sv-title{font-size:30px;} .sv-subtitle{font-size:13px;}.sv-section-title{font-size:20px;}}
    </style>""", unsafe_allow_html=True)
    st.markdown(f"""<div class="sv-hero">
      <img class="sv-logo" src="data:image/jpeg;base64,{SOLARVISION_LOGO}" alt="SolarVision logo">
      <div><div class="sv-eyebrow">SOLAR INTELLIGENCE</div><div class="sv-title">SolarVision</div>
      <p class="sv-subtitle">A clearer view of your panels.<br>Monitor production, inspect thermal images and plan maintenance.</p>
      <div class="sv-chips"><span class="sv-chip">Production monitoring</span><span class="sv-chip">Thermal inspection</span><span class="sv-chip">Maintenance insights</span></div></div>
    </div>""", unsafe_allow_html=True)
    st.sidebar.image(tab_logo, width=110)
    st.sidebar.markdown('### Control center')
    st.sidebar.caption('Choose your data and adjust the assessment.')
    st.sidebar.markdown('#### Production data')
    source = st.sidebar.radio('Production data', ['Historical test demo', 'Upload hourly CSV'])
    upload = st.sidebar.file_uploader('Hourly production CSV', type=['csv']) if source.startswith('Upload') else None
    drop = st.sidebar.slider('Shortfall threshold (%)', 5, 50, 20)/100
    st.sidebar.markdown('#### Cleaning economics')
    price = st.sidebar.number_input('Electricity price / kWh', min_value=0.0, value=2.0)
    cost = st.sidebar.number_input('Cleaning cost (same currency)', min_value=0.0, value=50.0)
    recovery = st.sidebar.slider('Expected recovery after cleaning', 0.0, 1.0, 0.8)
    scale = st.sidebar.number_input('Number of equivalent modules (estimate)', min_value=1.0, value=1.0)
    df = None
    loss = 0.0
    st.markdown('<div class="sv-section"><span class="sv-number">01</span><div><div class="sv-section-title">Production overview</div><div class="sv-section-sub">Compare actual output with expectations.</div></div></div>', unsafe_allow_html=True)
    try:
        source_file = TS / 'forecast_test_predictions_24h.csv' if source.startswith('Historical') else upload
        if source_file is not None:
            raw = pd.read_csv(source_file, index_col=0)
            if 'predicted_blend_W' in raw and st.checkbox('Use saved blended forecast'):
                raw['predicted_power_W'] = raw['predicted_blend_W']
            df, loss = analyze(raw, drop)
            actual_card, expected_card, alert_card = st.columns(3)
            actual_card.metric('Average actual output', f'{df.actual_power_W.mean():.1f} W')
            expected_card.metric('Average expected output', f'{df.predicted_power_W.mean():.1f} W')
            alert_card.metric('Hours with sustained alerts', int(df.alert.sum()), help='At least 3 of the last 6 hours show a production shortfall.')
            st.caption(f'{len(df):,} hourly readings · {df.index.min():%d %b %Y %H:%M} — {df.index.max():%d %b %Y %H:%M} UTC')
            st.line_chart(df[['actual_power_W', 'predicted_power_W']].rename(columns={'actual_power_W': 'Actual power (W)', 'predicted_power_W': 'Expected power (W)'}), color=['#49c6e5', '#f9c74f'], height=310)
            with st.expander('View alert readings'):
                readings = df.loc[df.alert, ['actual_power_W', 'predicted_power_W']].rename(columns={'actual_power_W': 'Actual power (W)', 'predicted_power_W': 'Expected power (W)'})
                readings.index.name = 'Time (UTC)'
                st.dataframe(readings)
            st.download_button('Download monitoring results', df.to_csv(), 'solarvision_results.csv', 'text/csv')
        else:
            st.info('Upload hourly production data to enable joint assessment.')
    except Exception as exc:
        st.error(f'Production data could not be analyzed: {exc}')
    if source.startswith('Historical'):
        st.info('Historical demo: saved test predictions from Laghouat, Algeria, 2022. No live sensor connection.')
    st.sidebar.markdown('#### Advanced tools')
    if st.sidebar.checkbox('Show advanced forecasting', value=False):
        with st.expander('Advanced: forecast next-day power'):
            st.caption('Upload a complete, preprocessed feature object. This prediction is separate from the historical monitoring chart.')
            features_file = st.file_uploader('Feature JSON', type=['json'])
            if features_file and st.button('Predict power'):
                try:
                    import joblib
                    names = list(joblib.load(TS/'models/best_forecast_24h_features.joblib'))
                    values = json.load(features_file)
                    if not isinstance(values, dict) or any(n not in values for n in names):
                        raise ValueError('All trained feature names must be supplied in a JSON object.')
                    x = pd.DataFrame([[float(values[n]) for n in names]], columns=names)
                    if not np.isfinite(x.to_numpy()).all():
                        raise ValueError('Features must be finite numbers.')
                    model = joblib.load(TS/'models/best_forecast_24h.joblib')
                    prediction = float(model.predict(x)[0])
                    if not np.isfinite(prediction):
                        raise ValueError('Model returned a nonfinite value.')
                    st.metric('24h-ahead module power (W)', f'{max(0, prediction):.3f}')
                except Exception as exc:
                    st.error(f'Forecast unavailable: {exc}')
    st.markdown('<div class="sv-section"><span class="sv-number">02</span><div><div class="sv-section-title">Thermal inspection</div><div class="sv-section-sub">Upload an inspection image to understand the panel condition.</div></div></div>', unsafe_allow_html=True)
    picture = st.file_uploader('Upload a thermal panel image', type=['png','jpg','jpeg'])
    label, confidence, mapping = None, 0.0, {}
    if not picture:
        st.info('Start an inspection by uploading a thermal image. JPG, JPEG and PNG are supported.')
    if picture:
        try:
            import tensorflow as tf
            from PIL import Image
            @st.cache_resource
            def load_thermal():
                return tf.keras.models.load_model(CV/'models/best_solar_cnn.keras', compile=False)
            model = load_thermal()
            mapping = json.loads((CV/'class_mapping.json').read_text())
            height, width, channels = model.input_shape[1:]
            if channels != 3:
                raise ValueError('Expected an RGB model.')
            image = Image.open(picture).convert('RGB')
            # Match training: TensorFlow bilinear resize, RGB, float32 / 255.
            batch = tf.image.resize(np.asarray(image, dtype=np.float32), (height,width))/255.0
            scores = np.asarray(model.predict(batch[None,...], verbose=0))[0]
            if scores.shape != (len(mapping['idx_to_class']),) or not np.isfinite(scores).all():
                raise ValueError('Model outputs do not match the class mapping.')
            best = int(scores.argmax())
            label, confidence = mapping['idx_to_class'][str(best)], float(scores[best])
            condition_card, score_card = st.columns(2)
            condition_card.metric('Detected condition', label)
            score_card.metric('Image model score', f'{confidence:.1%}')
            st.caption('Use thermal panel images similar to the inspection dataset. The result is an estimate.')

            st.subheader('Image explanation — Grad-CAM')
            try:
                heatmap, conv_name = thermal_gradcam(model, batch[None, ...], best)
                original_col, heat_col, overlay_col = st.columns(3)
                original_col.image(image, caption='Original thermal image', width=200)
                if not np.any(heatmap):
                    st.info('No positive class-specific activation was found for this image; no highlighted region is shown.')
                else:
                    colored, overlay = gradcam_images(image, heatmap)
                    heat_col.image(colored, caption='Grad-CAM: red = stronger contribution', width=200)
                    overlay_col.image(overlay, caption='Explanation over the original image', width=200)
                st.caption('Highlights regions contributing to the predicted class. This is an approximate explanation, not a fault boundary or a temperature measurement.')
            except Exception as cam_error:
                st.image(image, caption='Original thermal image', width=200)
                st.warning('The classification is available, but its visual explanation could not be generated.')
                with st.expander('Explanation error details'):
                    st.code(str(cam_error))

            with st.expander('View all image results'):
                st.dataframe(pd.DataFrame({'Class':[mapping['idx_to_class'][str(i)] for i in range(len(scores))], 'Score':scores}).sort_values('Score', ascending=False).style.format({'Score': '{:.1%}'}))
        except Exception as exc:
            st.error(f'Thermal classification unavailable: {exc}')
    st.markdown('<div class="sv-section"><span class="sv-number">03</span><div><div class="sv-section-title">Maintenance insights</div><div class="sv-section-sub">Bring production and inspection evidence together.</div></div></div>', unsafe_allow_html=True)
    matched = st.checkbox('The image and readings are from the same panel/site and inspection period', value=False)
    with st.expander('Assessment settings'):
        threshold = st.slider('Minimum image model score', 0.5, 0.99, 0.7)
    net = loss * scale * recovery * price - cost
    benefit_card, evidence_card = st.columns(2)
    benefit_card.metric('Estimated net cleaning benefit', f'{net:,.2f}' if df is not None else '—')
    evidence_card.metric('Evidence status', 'Linked' if matched and label is not None and df is not None else 'Not linked')
    st.caption('Estimate based on your inputs; actual savings may differ.')
    with st.expander('How the estimate is calculated'):
        st.write('Energy shortfall on alert days × equivalent modules × expected recovery × electricity price − cleaning cost.')
    if df is None:
        st.info('Joint assessment requires valid production data.')
    else:
        recommendation = maintenance(bool(df.alert.any()), label, confidence, matched, net, threshold)
        if recommendation.startswith('Consider cleaning'):
            st.success(recommendation)
        elif matched and label and confidence < threshold:
            st.warning(recommendation)
        else:
            st.info(recommendation)
        if matched and label and confidence >= threshold:
            info = mapping.get('priority_info', {}).get(label, {})
            st.write('Maintenance priority:', info.get('level', 'Review'))
            action = info.get('action', 'Manual review')
            if label == 'Soiling':
                action = 'Schedule washing'
            st.write('Suggested action:', action)

    st.markdown('<div class="sv-footer">SolarVision · Production & thermal insights<br>Decision support based on uploaded or historical data. No live sensor connection.</div>', unsafe_allow_html=True)


if __name__ == '__main__':
    main()
